module Outer(scale: number) {
 group Scope {
  const half: number = @scale / 2
  module Inner(width: number) {
   point P = coordinate(x: @width + 1, y: -9)
   point Q = coordinate(x: -3, y: @width * 2)
   line Edge = segment(start: @P, end: @Q)
  }
  instance Child = Inner(width: @half)
 }
}
instance Left = Outer(scale: 18)
instance Right = Outer(scale: 42)

